#!/usr/local/bin/python3
# send TCP reset packet with faked ack 0 that is behind the sequence

import os
import threading
from addr import *
from scapy.all import *

#
# we can not use scapy's sr() function as receive side
# ignores the packet we expect to see.  The challenge ACK
# generated by pf does not match the sequence of our bogus SYN.
#
class Sniff1(threading.Thread):
	filter = None
	captured = None
	packet = None
	def run(self):
		self.captured = sniff(iface=LOCAL_IF, filter=self.filter,
		    count=1, timeout=5)
		if self.captured:
			self.packet = self.captured[0]

tport=os.getpid() & 0xffff

ip=IP(src=FAKE_NET_ADDR, dst=REMOTE_ADDR)

print("Send SYN packet, receive SYN+ACK")
syn=TCP(sport=tport, dport='discard', flags='S', seq=2**24,
    window=(2**16)-1)
synack=sr1(ip/syn, timeout=5)
if synack is None:
	print("ERROR: no matching SYN+ACK packet received")
	exit(1)
if synack.window < 16:
	print("ERROR: remote window %u too small for backwards sequence" %
	    synack.window)
	exit(1)

print("Send ACK packet to finish handshake.")
ack=TCP(sport=synack.dport, dport=synack.sport, flags='A',
    seq=syn.seq+1, ack=synack.seq+1)
send(ip/ack)

# Resets are allowed within a window backwards of seqlo, but only if
# they acknowledge seqlo of the peer perfectly.  As pf replaces a wire
# ack 0 with the tracked seqlo of the peer, such a reset used to look
# like a perfect ack although the sender never knew the number.  Chose
# a sequence inside the backwards window, but not one of the exact
# matches seqlo-1, seqlo, seqlo+1 that are accepted by design.
old_seq=syn.seq-(synack.window//2)

print("Send reset with ack 0 and sequence %u behind syn %u." %
    (old_seq, syn.seq))
fake_rst=TCP(sport=syn.sport, dport=syn.dport, flags='AR',
    seq=old_seq, ack=0, window=(2**16)-1)
send(ip/fake_rst)

print("Connection must persist, send bogus SYN, expect challenge ACK")
bogus_syn=TCP(sport=syn.sport, dport=syn.dport, flags='S', seq=1,
    window=(2**16)-1)
sniffer = Sniff1();
sniffer.filter = "src %s and tcp port %u and dst %s and tcp port %u " \
    "and tcp[tcpflags] = tcp-ack" % (ip.dst, syn.dport, ip.src, syn.sport)
sniffer.start()
time.sleep(1)
send(ip/bogus_syn)
sniffer.join(timeout=7)
challenge_ack = sniffer.packet
if challenge_ack is None:
	print("ERROR: no challenge ACK received, forged reset killed state")
	exit(1)
if challenge_ack.seq != synack.seq+1 or challenge_ack.ack != syn.seq:
	print("ERROR: expecting seq %d ack %d, got seq %d ack %d in "
	    "challenge ack" %
	    (synack.seq+1, syn.seq, challenge_ack.seq, challenge_ack.ack))
	exit(1)

print("Send reset to cleanup the connection")
rst=TCP(sport=synack.dport, dport=synack.sport, flags='RA',
    seq=synack.ack, ack=synack.seq)
send(ip/rst)

exit(0)
